import{_ as p,a0 as r,w as o,s as d,I as n,x as s,a1 as e,A as t,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"用 Ansible 来交付 Vagrant  实例 | LCTT x X-CMD","titleTemplate":false,"description":"用 Ansible 来交付 Vagrant  实例 | LCTT (201610) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Ansible 来交付 Vagrant  实例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Ansible 来交付 Vagrant  实例 | LCTT (201610) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201610/20160915 Using Ansible to Provision Vagrant Boxes","title":"用 Ansible 来交付 Vagrant  实例","tag":"201610","desc":""},"relativePath":"201610/20160915 Using Ansible to Provision Vagrant Boxes.md","filePath":"[post].md"}'),g={name:"201610/20160915 Using Ansible to Provision Vagrant Boxes.md"};function b(h,a,k,u,m,c){const i=r("Link");return o(),d("div",null,[a[25]||(a[25]=n("h1",{id:"用-ansible-来交付-vagrant-实例",tabindex:"-1"},[s("用 Ansible 来交付 Vagrant 实例 "),n("a",{class:"header-anchor",href:"#用-ansible-来交付-vagrant-实例","aria-label":"Permalink to “用 Ansible 来交付 Vagrant  实例”"},"​")],-1)),a[26]||(a[26]=n("p",null,[n("img",{src:"https://i1.wp.com/cdn.fedoramagazine.org/wp-content/uploads/2016/08/vagrant-plus-ansible.jpg?w=1352&ssl=1",alt:""})],-1)),n("p",null,[a[1]||(a[1]=s("Ansible 是一款系统管理员进行自动化运维的强大工具。Ansible 让配置、交付、管理各种容器，软件部署",-1)),e(i,{href:"https://ansible.com/"},{default:t(()=>[...a[0]||(a[0]=[s("变得非常简单",-1)])]),_:1}),a[2]||(a[2]=s("。基于轻量级模块的架构非常适合系统管理，一个优点就是如果某个节点没有被 Ansible 管理的话，它的资源就不会被使用。",-1))]),n("p",null,[a[4]||(a[4]=s("这篇文章介绍用 Ansible 来配置 ",-1)),e(i,{href:"https://www.vagrantup.com/"},{default:t(()=>[...a[3]||(a[3]=[s("Vagrant 实例",-1)])]),_:1}),a[5]||(a[5]=s("，它是一个配置好的基础虚拟机映像，包含了开发环境中需要用到的工具。你可以用它来部署开发环境，然后和其他成员协同工作。用 Ansible，你可以用你的开发包自动化交付 Vagrant 实例。",-1))]),n("p",null,[a[7]||(a[7]=s("我们用 Fedora 24 做主机，用 ",-1)),e(i,{href:"https://centos.org/"},{default:t(()=>[...a[6]||(a[6]=[s("CentOS",-1)])]),_:1}),a[8]||(a[8]=s(" 7 来作 Vagrant 实例。",-1))]),a[27]||(a[27]=l(`<h3 id="设置工作环境" tabindex="-1">设置工作环境 <a class="header-anchor" href="#设置工作环境" aria-label="Permalink to “设置工作环境”">​</a></h3><p>在用 Ansible 配置 Vagrant 实例时，你需要做几件准备的事情。首先在宿主机上安装 Ansible 和 Vagrant，在你的主机上运行下面的命令来安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install ansible vagrant vagrant-libvirt</span></span></code></pre></div><p>上面的命令将 Ansible 和 Vagrant 在你的宿主机上，以及包括 Vagrant 的 libvirt 接口。Vagrant 并没有提供托管你的虚拟机的功能，需要第三方工具比如：libirt、VirtualBox、VMWare 等等。这些工具可以直接与你的 Fedora 系统上的 libvirt 和 KVM 协同工作。</p><p>接着确认你的账户在正确的 wheel 用户组当中，确保你可以运行系统管理员命令。如果你的账号在安装过程中就创建为管理员，那么你就肯定在这个用户组里。运行下面的命令查看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>id | grep wheel</span></span></code></pre></div><p>如果你能看到输出，那么你的账户就在这个组里，可以进行下一步。如果没有的话，你需要运行下面的命令，这一步需要你提供 root 账户的密码，将 &lt;username&gt; 换成你的用户名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>su -c &#39;usermod -a -G wheel &lt;username&gt;&#39;</span></span></code></pre></div><p>然后，你需要注销然后重新登录，确保在用户组里。</p><p>现在要建立你的第一个 Vagrant 实例了，你需要用 Ansible 来配置它。</p><h3 id="设置-vagrant-实例" tabindex="-1">设置 Vagrant 实例 <a class="header-anchor" href="#设置-vagrant-实例" aria-label="Permalink to “设置 Vagrant 实例”">​</a></h3><p>配置一个镜像实例之前，你需要先创建它。创建一个目录，存放 Vagrant 实例 相关的文件，并且将它作为当前工作目录，用下面这条命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir -p ~/lampbox &amp;&amp; cd ~/lampbox</span></span></code></pre></div><p>在创建镜像实例之前，你需要搞清楚目的，这个镜像实例是一个运行 CentOS 7 基础系统，模板包括 Apache 的 Web 服务，MariaDB（MySQL 原开发者创建的一个流行的开源数据库）数据库和 PHP 服务。</p><p>初始化 Vagrant 实例，用 <code>vagrant init</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vagrant init centos/7</span></span></code></pre></div><p>这个命令初始化 Vagrant 实例，并创建一个名为 Vagrantfile 的文件，包含一些预先配置的变量。打开并编辑它，下面的命令显示了用于这次配置的基本镜像实例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>config.vm.box = &quot;centos/7&quot;</span></span></code></pre></div><p>现在设置端口转发，以便你配置完毕 Vagrant 实例并让它运行起来之后可以测试它。将下述配置加入到 Vagrantfile 的最终的 <code>end</code> 语句之前：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>config.vm.network &quot;forwarded_port&quot;, guest: 80, host: 8080</span></span></code></pre></div><p>这个命令将 Vagrant 实例 的 80 端口映射为主机的 8080 端口。</p><p>下一步是设置 Ansible 作为配置 Vagrant 实例的工具，将下述配置加入到 Vagrantfile 的 <code>end</code> 语句之前，将 Ansible 作为配置工具（provisioning provider）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>config.vm.provision :ansible do |ansible|</span></span>
<span class="line"><span>  ansible.playbook = &quot;lamp.yml&quot;</span></span>
<span class="line"><span>end</span></span></code></pre></div><p>（必须将这三行在最后的 <code>end</code> 语句之前加入）注意 <code>ansible.playbook = &quot;lamp.yml&quot;</code> 这一句定义了配置镜像实例的 Ansible playbook 的名字。</p><h3 id="创建-ansible-playbook" tabindex="-1">创建 Ansible playbook <a class="header-anchor" href="#创建-ansible-playbook" aria-label="Permalink to “创建 Ansible playbook”">​</a></h3><p>在 Ansible 之中，playbook 是指在你的远端节点执行的策略，换句话说，它管理远端节点的配置和部署。详细的说，playbook 是一个 Yaml 文件，在里面写入你要在远端节点上将要执行的任务。所以，你需要创建一个名为 lamp.yml 的 playbook 来配置镜像实例。</p><p>在 Vagrantfile 相同的目录里创建一个 lamp.yml 文件，将下面的内容粘贴到文件当中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---</span></span>
<span class="line"><span>- hosts: all</span></span>
<span class="line"><span>  become: yes</span></span>
<span class="line"><span>  become_user: root</span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>  - name: Install Apache</span></span>
<span class="line"><span>    yum: name=httpd state=latest</span></span>
<span class="line"><span>  - name: Install MariaDB</span></span>
<span class="line"><span>    yum: name=mariadb-server state=latest</span></span>
<span class="line"><span>  - name: Install PHP5</span></span>
<span class="line"><span>    yum: name=php state=latest</span></span>
<span class="line"><span>  - name: Start the Apache server</span></span>
<span class="line"><span>    service: name=httpd state=started</span></span>
<span class="line"><span>  - name: Install firewalld</span></span>
<span class="line"><span>    yum: name=firewalld state=latest</span></span>
<span class="line"><span>  - name: Start firewalld</span></span>
<span class="line"><span>    service: name=firewalld state=started</span></span>
<span class="line"><span>  - name: Open firewall</span></span>
<span class="line"><span>    command: firewall-cmd --add-service=http --permanent</span></span></code></pre></div><p>每一行代表的意思：</p><ul><li><code>hosts: all</code> 指定该 playbook 需要在 Ansible 配置文件中定义的所有主机上都执行，因为还没定义主机， playbook 将只在本地运行。</li><li><code>sudo: true</code> 表明该任务需要用 root 权限运行。（LCTT 译注：此语句上述配置中缺失。）</li><li><code>tasks:</code> 指定当 playbook 运行是需要执行的任务，在这一节之下： <ul><li><code>name: ...</code> 描述任务的名字</li><li><code>yum: ...</code> 描述该任务应该由 yum 模块执行，可选的 key=value 键值对将由 yum 模块所使用。</li></ul></li></ul><p>当 playbook 运行时，它会安装最新的 Apache Web 服务（http），MariaDB 和 PHP。当安装完毕并启动防火墙 firewalld，给 Apache 打开一个端口。你可以通过编写 playbook 来完成这些。现在可以配置它了。</p><h3 id="配置镜像-实例" tabindex="-1">配置镜像 实例 <a class="header-anchor" href="#配置镜像-实例" aria-label="Permalink to “配置镜像 实例”">​</a></h3><p>用 Ansible 配置 Vagrant 实例只需要以下几步了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vagrant up --provider libvirt</span></span></code></pre></div><p>上面的命令运行 Vagrant 实例，将实例的基础镜像下载到宿主机当中（如果还没下载的话），然后运行 lamp.yml 来进行配置。</p><p>如果一切正常，输出应该和下面的例子类似：</p><p><img src="https://i1.wp.com/cdn.fedoramagazine.org/wp-content/uploads/2016/08/vagrant-ansible-playbook-run.png?w=574&amp;ssl=1" alt=""></p><p>这个输出显示镜像实例已经被配置好了，现在检查服务是否可用，在宿主机上打开浏览器，输入 <code>http://localhost:8080</code>，记住本地主机的 8080 端口是 Vagrant 实例映射过来的 80 端口。你应该可以看到如下的 Apache 的欢迎界面。</p><p><img src="https://i0.wp.com/cdn.fedoramagazine.org/wp-content/uploads/2016/08/vagrant-ansible-apache-up.png?w=1004&amp;ssl=1" alt=""></p>`,39)),n("p",null,[a[10]||(a[10]=s("要修改你的 Vagrant 实例，你可以修改 lamp.yml，你能从 Ansible 的",-1)),e(i,{href:"http://docs.ansible.com/ansible/index.html"},{default:t(()=>[...a[9]||(a[9]=[s("官网",-1)])]),_:1}),a[11]||(a[11]=s("上找到很多文章。然后运行下面的命令来重新配置：",-1))]),a[28]||(a[28]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vagrant provision</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>现在我们知道怎么用 Ansible 来配置 Vagrant 实例了。这只是一个基本的例子，但是你可以用这些工具来实现不同的例子。比如你可以用所需工具的最新版本来部署一个完整的应用。现在你可以用 Ansible 来配置你自己的远端服务器和容器了。</p><hr>',4)),n("p",null,[a[13]||(a[13]=s("via: ",-1)),e(i,{href:"https://fedoramagazine.org/using-ansible-provision-vagrant-boxes/"},{default:t(()=>[...a[12]||(a[12]=[s("https://fedoramagazine.org/using-ansible-provision-vagrant-boxes/",-1)])]),_:1})]),n("p",null,[a[17]||(a[17]=s("作者：",-1)),e(i,{href:"http://h4xr.id.fedoraproject.org/"},{default:t(()=>[...a[14]||(a[14]=[s("Saurabh Badhwar",-1)])]),_:1}),a[18]||(a[18]=s(" 译者：",-1)),e(i,{href:"https://github.com/jiajia9linuxer"},{default:t(()=>[...a[15]||(a[15]=[s("jiajia9linuxer",-1)])]),_:1}),a[19]||(a[19]=s(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...a[16]||(a[16]=[s("wxy",-1)])]),_:1})]),n("p",null,[a[22]||(a[22]=s("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[20]||(a[20]=[s("LCTT",-1)])]),_:1}),a[23]||(a[23]=s(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...a[21]||(a[21]=[s("Linux中国",-1)])]),_:1}),a[24]||(a[24]=s(" 荣誉推出",-1))])])}const V=p(g,[["render",b]]);export{v as __pageData,V as default};
